INSERT INTO DimTime (SK_TimeID, TimeValue, HourID, HourDesc, MinuteID, MinuteDesc, SecondID, SecondDesc, MarketHoursFlag, OfficeHoursFlag) SELECT SK_TimeID, TimeValue, HourID, HourDesc, MinuteID, MinuteDesc, SecondID, SecondDesc, CASE WHEN UPPER(MarketHoursFlag) = 'TRUE' THEN TRUE ELSE FALSE END AS MarketHoursFlag, CASE WHEN UPPER(OfficeHoursFlag) = 'TRUE' THEN TRUE ELSE FALSE END AS OfficeHoursFlag FROM Source.Time;
